import { FileSignatureIcon } from 'lucide-vue-next';
import type { ProjectStatus } from '~/client';

/**
 * `is_unique_only` lingers in the URL as `false` after toggling the "unique" filter
 * off; treat that off-value as the default so it does not count as an active filter.
 */
export const SIGNATURES_FILTER_DEFAULTS = { is_unique_only: false };

const signaturesContent: GuidedEmptyContent = {
  icon: FileSignatureIcon,
  title: 'No signatures yet',
  description: 'Signatures you submit for this project will appear here.',
  actions: [{ label: 'Go to Verification', to: { name: 'verification' } }],
};

interface SignaturesGuidedEmptyParams {
  projectId: string;
  status?: ProjectStatus;
}

export function buildSignaturesGuidedEmpty({ projectId, status }: SignaturesGuidedEmptyParams): GuidedEmptyConfig {
  const isActive = status === 'active';

  return {
    canvasser: signaturesContent,
    subcontractor_canvasser: signaturesContent,
    manager: {
      icon: FileSignatureIcon,
      title: 'No signatures yet',
      // Only active projects can be imported into, so only then do we surface
      // the import action and mention it in the description.
      description: isActive
        ? 'Signatures submitted by canvassers for this project will appear here. Import a petition to add signatures.'
        : 'Signatures submitted by canvassers for this project will appear here.',
      actions: isActive
        ? [
            {
              label: 'Import Petition',
              to: { name: 'verification-ballots-configuration', query: { project_id: projectId } },
            },
          ]
        : [],
    },
    admin: {
      icon: FileSignatureIcon,
      title: 'No signatures yet',
      description: 'Signatures submitted by canvassers for this project will appear here.',
    },
  };
}
