import { createExportSubmittedSignaturesJob } from '~/client';
import type {
  CreateExportSubmittedSignaturesJobResponse,
  SubmittedSignaturesExportRequest,
  CreateExportSubmittedSignaturesJobData,
} from '~/client';

export const useExportSubmittedSignatures = defineMutation(() => {
  const {
    mutateAsync: exportSubmittedSignaturesList,
    asyncStatus,
    data,
  } = useMutation({
    mutation: (
      data: NonNullable<SubmittedSignaturesExportRequest>
    ): Promise<CreateExportSubmittedSignaturesJobResponse> =>
      createExportSubmittedSignaturesJob({ composable: '$fetch', body: ref(data) }),
    onError: (error) => {
      showToastError(error);
    },
  });

  return {
    exportSubmittedSignaturesList,
    isExportSubmittedSignaturesList: computed(() => asyncStatus.value === 'loading'),
    data,
  };
});
