<template>
  <Dialog
    v-model:open="open"
    @update:open="
      (value) => {
        if (value) exportFormat = { name: 'CSV', value: 'csv' };
      }
    "
  >
    <DialogTrigger as-child>
      <Button :disabled="disabled" :prepend-icon="FileUpIcon">Export</Button>
    </DialogTrigger>
    <DialogContent>
      <DialogHeader>
        <DialogTitle>Export Signatures List</DialogTitle>
        <DialogDescription> You can export the list of submitted signatures in CSV or XLS format. </DialogDescription>
      </DialogHeader>
      <LabeledSelect v-model="exportFormat" :items="exportFormats" label="Format" />
      <DialogFooter>
        <DialogClose as-child>
          <Button variant="outline">Cancel</Button>
        </DialogClose>
        <Button
          :loading="isExportSubmittedSignaturesList"
          :disabled="isExportSubmittedSignaturesList"
          @click="exportUsers"
          >Export</Button
        >
      </DialogFooter>
    </DialogContent>
  </Dialog>
</template>

<script setup lang="ts">
import { FileUpIcon } from 'lucide-vue-next';
import { exportFormats } from '~/constants/export';
import { useExportSubmittedSignatures } from '~/mutations/project/exportSignatures';
import type { GetSubmittedSignaturesListData } from '~/client';
//TODO: After updates with users/project user assignments tables, unify this export with users exports

interface Props {
  projectId: string;
  disabled?: boolean;
  params: GetSubmittedSignaturesListData['query'];
}

const props = defineProps<Props>();

const exportFormat = ref<SelectItem<'csv' | 'xls'>>({ name: 'CSV', value: 'csv' });
const open = ref<boolean>(false);

const { isExportSubmittedSignaturesList, exportSubmittedSignaturesList, data } = useExportSubmittedSignatures();

async function exportUsers() {
  if (!exportFormat.value) return;
  const { timezone } = useUserRole();

  await exportSubmittedSignaturesList({
    ...props.params,
    timezone: timezone.value,
    file_type: exportFormat.value.value || undefined,
  });
  if (data.value?.id)
    await navigateTo({
      name: 'exports-id',
      params: { id: data.value.id },
    });
}
</script>
