<template>
  <ProjectSignaturesFilter :project-id="projectId" :params="params" />
  <Card>
    <CardHeader class="py-4 flex flex-row flex-wrap justify-between">
      <h3 class="text-lg font-semibold">Submitted Signatures</h3>
      <ExportSignaturesList
        v-if="isAdminOrManager"
        :project-id="projectId"
        :disabled="!submitted_signatures || submitted_signatures?.total_count === 0"
        :params="params"
      />
    </CardHeader>
    <CardContent class="flex flex-col gap-4">
      <AppLoader v-if="isLoading" variant="inline" subject="submitted signatures" />
      <AppError v-else-if="error" title="Failed to load submitted signatures" :error="error" />
      <AppGuidedEmpty v-else-if="showGuided && guidedContent" v-bind="guidedContent" variant="table" />
      <AppEmpty
        v-else-if="!submitted_signatures || submitted_signatures.items.length === 0"
        subject="submitted signatures"
        variant="table"
      />
      <template v-else>
        <Card
          v-for="item in submitted_signatures?.items"
          :key="item.id"
          :class="cn('px-4 py-2 w-full bg-accent border-input', item.id ? 'cursor-pointer' : '')"
          @click="itemClick(item.id)"
        >
          <div class="flex flex-row items-center justify-between">
            <div>
              <p class="text-lg font-semibold flex gap-2 flex-wrap">
                <span class="break-all">{{ item.signatory_info.first_name || '_' }}</span>
                <span class="break-all">{{ item.signatory_info.last_name || '_' }}</span>
              </p>
              <span v-if="formatAddress(item.signatory_info)" class="text-sm leading-6 block">
                Address: {{ formatAddress(item.signatory_info) }}
              </span>
              <span v-else class="text-sm leading-6 text-red-500 block"> No Address </span>
              <span
                v-if="item.signed_at"
                class="text-sm leading-6"
                :class="item.error_type === 'invalid_signed_date' ? 'text-red-500' : ''"
              >
                Date Signed: {{ formatDateTzToFormat(item.signed_at, 'MM/dd/yyyy', timezone) }}
              </span>
              <span v-else class="text-sm leading-6 text-red-500">No Date Signed</span>
            </div>
            <div class="flex flex-col gap-1 items-end">
              <Badge :variant="getSubmittedSignaturesBadge(item.status).variant">{{
                getSubmittedSignaturesBadge(item.status).label
              }}</Badge>
              <span class="text-sm leading-6 text-muted-foreground">
                from {{ getSubmittedSignatureSourceLabel(item.source) }}
              </span>
              <span class="text-sm leading-6 text-muted-foreground">
                Submitted at {{ formatDateTzToFormat(item.created_at, 'MM/dd/yyyy hh:mm aaa', timezone) }}
              </span>
            </div>
          </div>
        </Card>
        <AppPagination
          v-if="submitted_signatures?.total_count && submitted_signatures.total_count > 0"
          :page="params.page"
          :size="params.size"
          :total="submitted_signatures.total_count"
          label="signatures"
        />
      </template>
    </CardContent>
  </Card>
</template>

<script setup lang="ts">
import { cn } from '@/lib/utils';
import { getSubmittedSignaturesBadge } from '~/constants/verifications/submittedSignatureStatus';
import { getSubmittedSignatureSourceLabel } from '~/constants/verifications/submittedSignatureSource';
import { useQuery } from '@pinia/colada';
import { getSubmittedSignaturesList, type ProjectStatus, type SignatoryForm } from '~/client';
import type {
  GetSubmittedSignaturesListData,
  ProjectShortInfo,
  SortType,
  SubmittedSignatureSortBy,
  SubmittedSignatureStatus,
  ProjectEditTabsStatusResponse,
  SubmittedSignatureSource,
  MatcherName,
  SignatureErrorType,
} from '~/client';
import ProjectSignaturesFilter from '~/components/project/signatures/ProjectSignaturesFilter.vue';
import { buildSignaturesGuidedEmpty, SIGNATURES_FILTER_DEFAULTS } from '~/constants/guidedEmpty/signatures';

definePageMeta({
  backGroup: 'project-details',
  backLabel: 'project',
});

interface Props {
  projectId: string;
  projectShortInfo?: ProjectShortInfo;
  tabStatus?: ProjectEditTabsStatusResponse;
}

const props = defineProps<Props>();
const { timezone, isAdminOrManager } = useUserRole();
//TODO refactor useVoiceVerificationList and ProjectVoiceVerifications component logic and usage. Temporary fix error handling

async function itemClick(signature_id: string | undefined) {
  if (isAdminOrManager.value && signature_id)
    await navigateTo({
      name: 'verification-ballots-signatures-submitted-id',
      params: { id: signature_id },
    });
}

const params = computed<GetSubmittedSignaturesListData['query']>(() => {
  const { subcontractor_company_ids, include_unassigned } = parseSubcontractorCompanyFilter(
    useRoute().query.subcontractor_company_ids
  );

  return {
    ...parsePagination(useRoute().query, { size: 20 }),
    sort_by: (useRoute().query.sort_by as SubmittedSignatureSortBy) || 'created_at',
    sort_type: isSortType(useRoute().query.sort_type as string) ? (useRoute().query.sort_type as SortType) : 'desc',
    search_query: (useRoute().query.search_query as string) || undefined,
    statuses: processArrayQueryParameterFromUrl<SubmittedSignatureStatus>(
      useRoute('verification-ballots-signatures-submitted-id').query.statuses
    ),
    sources: processArrayQueryParameterFromUrl<SubmittedSignatureSource>(
      useRoute('verification-ballots-signatures-submitted-id').query.sources
    ),
    canvasser_ids: processArrayQueryParameterFromUrl<string>(
      useRoute('verification-ballots-signatures-submitted-id').query.canvasser_ids
    ),
    manager_ids: processArrayQueryParameterFromUrl<string>(
      useRoute('verification-ballots-signatures-submitted-id').query.manager_ids
    ),
    subcontractor_company_ids,
    include_unassigned,
    voter_regions: processArrayQueryParameterFromUrl<string>(
      useRoute('verification-ballots-signatures-submitted-id').query.voter_regions
    ),
    project_ids: [props.projectId],
    created_date_from: (useRoute().query.created_date_from as string) || undefined,
    signed_date_from: (useRoute().query.signed_date_from as string) || undefined,
    created_date_to: (useRoute().query.created_date_to as string) || undefined,
    signed_date_to: (useRoute().query.signed_date_to as string) || undefined,
    matching_results: processArrayQueryParameterFromUrl<MatcherName>(useRoute().query.matching_results),
    error_types: processArrayQueryParameterFromUrl<SignatureErrorType>(useRoute().query.error_types),
    timezone: timezone.value,
    is_unique_only: (useRoute().query.is_unique_only === 'true' ? true : undefined) || undefined,
  };
});

const {
  data: submitted_signatures,
  error,
  isLoading,
} = useQuery({
  key: () => ['submitted-signatures.list', params.value],
  query: () =>
    getSubmittedSignaturesList({
      composable: '$fetch',
      query: params,
    }),
  enabled: () => !!props.projectId,
});

const isEmpty = computed(() => !submitted_signatures.value || submitted_signatures.value.items.length === 0);

const { guidedContent, showGuided } = useGuidedEmpty(
  () => buildSignaturesGuidedEmpty({ projectId: props.projectId, status: props.projectShortInfo?.status }),
  isEmpty,
  SIGNATURES_FILTER_DEFAULTS
);

function formatAddress(item: SignatoryForm) {
  let address = '';
  address += item.address_1 ? item.address_1 + ', ' : '';
  address += item.address_2 ? item.address_2 + ', ' : '';
  address += item.county ? item.county + ', ' : '';
  address += item.city ? item.city + ', ' : '';
  address += item.state ? item.state + ', ' : '';
  address += item.zip_code ? item.zip_code : '';
  return address;
}
</script>
